export const enhanceCaliforniaGuide = (
  stateSlug: string,
  citySlug: string,
  guide: GuidePageData
): GuidePageData => {
  if (stateSlug !== "california") return guide;
  const e = ca[citySlug];
  if (!e) return guide;
  const place = guide.city ?? citySlug.replace(/-/g, " ");
  return {
    ...guide,
    hero: {
      ...guide.hero,
      alt: `${place}, California travel guide`,
      subheadline: `Plan ${place} with destination-specific sights, outdoor context, practical timing, and accurate nearby excursions.`
    },
    overview: [e.overview],
    highlights: e.highlights.map(([title, description]) => ({ title, description })),
    thingsToDo: e.things.map(([title, description]) => ({
      title,
      description: `${description} Build this stop into the day based on current hours, access, weather and local conditions rather than treating it as a generic checklist item.`
    })),
    bestTimeToVisit: {
      title: `When to visit ${place}`,
      bullets: [e.season, "Check current weather, closures and event calendars before locking in outdoor plans.", "Reserve high-demand lodging, tours and timed experiences early for peak weekends."]
    },
    travelTips: e.tips,
    faq: [
      { q: `How long should I spend in ${place}?`, a: `One to three days works for most travelers, depending on whether ${place} is the main destination or part of a wider California itinerary.` },
      { q: `Do I need a car in ${place}?`, a: `It depends on the destination core and your excursions. Use walking, cycling, rail or local transit where practical, and plan a car only for places that genuinely require one.` }
    ],
    seoLinks: { officialTourism: e.tourism ?? "https://www.visitcalifornia.com/" },
    aboutCity: undefined
  };
};
